/**
 * Implements the core Host Config abstraction for custom rendering.
 */
function createMiniReconciler() {
  return {
    createInstance(type, props = {}) {
      return {
        type,
        props: { ...props },
        children: []
      };
    },
    createTextInstance(text) {
      return {
        type: 'TEXT',
        text: String(text)
      };
    },
    appendChild(parent, child) {
      parent.children.push(child);
    }
  };
}
